# Public API (cm:*)
  @api cm:setContext(newTake)  @ 430-435
      @contract  setContext(nil) clears take+track; setContext(take) derives track via GetMediaItemTrack  @ 428
      @contract  refreshes all persisted caches (transient resets to {}) and fires configChanged {}  @ 429
  @api cm:clearTake()  @ 437-442
  @api cm:boundTake()  @ 445
      @contract  bound take pointer; nil when context is cleared (take/track tiers resolve off empty)  @ 444
  @api cm:boundTrack()  @ 448
      @contract  bound track pointer; nil when context is cleared (track tier resolves off empty)  @ 447
  @api cm:setTrack(newTrack)  @ 450-455
  @api cm:pollUndo()  @ 458
      @contract  delegates to the engine watcher; cm's watch group reloads tiers and fires configChanged  @ 457
  @api cm:isDeclared(key)  @ 495
      @contract  non-raising existence test against the schema; true iff key is declared  @ 494
  @api cm:get(key, opts)  @ 502-509
      -- pick is orthogonal to the merge mode: it indexes whatever that mode resolved, so only the
      -- one entry crosses the boundary. A nil pick is indistinguishable from none (see the spec).
  @api cm:getAt(level, key)  @ 512-521
      @contract  reads single tier only (no merge, no defaults); key nil → whole-cache clone  @ 511
  @api cm:valueFor(handle, scope, key)  @ 524-531
      @contract  single-tier value for a foreign take/track handle (ps:getAt); no merge or defaults  @ 523
  @api cm:defaultFor(key)  @ 534-537
      @contract  deep-copy of the schema default for key (no tiers, no merge); raises on unknown key  @ 533
  -- Writing
  @api cm:set(level, key, value)  @ 542-552
      @contract  deep-copies value into tier cache, persists, fires targeted configChanged  @ 541
  @api cm:remove(level, key)  @ 555-566
      @contract  removes key from named tier; no-op (no signal) if that tier's cache is unloaded  @ 554
  @api cm:assign(level, updates)  @ 569-583
      @contract  validates all keys before any write (all-or-nothing); REMOVE deletes; fires signal  @ 568

